9	/**
10	 * GET /api/clients/{clientId}/statement — one client's statement: all of that client's invoices,
11	 * gathered from every one of their projects, each with how much is still left to pay (the billed
12	 * amount minus everything paid against it), and the outstanding total — the sum of what is still due
13	 * across those invoices.
14	 */
